// Offline testbench for the two-leg DC/DC shipboard example.
// The solver header and adapter are generated by run.py, without header patches.
#include "config.hpp"
#include "solver_adapter.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>

int main(int argc, char** argv)
{
    if (argc != 4) {
        std::cerr << "Usage: simulate busstep|acstep duration output_prefix\n";
        return 1;
    }
    const std::string scenario = argv[1], prefix = argv[3];
    const double duration = std::strtod(argv[2], nullptr);
    if ((scenario != "busstep" && scenario != "acstep") || !std::isfinite(duration) || duration <= 0)
        return 1;
    const double dt = DEMO_DT, controlDt = 50e-9, carrierHz = 100000, fundamentalHz = 60;
    const double eventTime = scenario == "busstep" ? .5 : 10.133;
    const double focusStart = scenario == "busstep" ? .47 : 10.09;
    const double focusEnd = scenario == "busstep" ? .58 : 10.20;
    const std::int64_t steps = std::llround(duration / dt);
    const std::int64_t controlEvery = std::llround(controlDt / dt);
    const std::int64_t carrierTicks = std::llround(1 / (carrierHz * controlDt));
    const std::int64_t activationTick = std::llround(20e-6 / controlDt);
    const std::int64_t inverterTick = std::llround(.004 / controlDt);
    const std::int64_t eventTick = std::llround(eventTime / controlDt);
    const std::int64_t globalEvery = std::llround(100e-6 / dt);
    const std::int64_t focusEvery = std::llround(2e-6 / dt);
    if (controlEvery < 1 || std::abs(controlEvery * dt - controlDt) > 1e-18)
        return 1;
    const double pi = std::acos(-1.0);
    Sample sample = {};
    bool dcdcGates[2][2] = {}, inverterGates[6][3] = {}, enabled[8] = {};
    double carrier = 0, modulation = 0, duty = .5;
    std::ofstream csv(prefix + ".csv");
    if (!csv) return 1;
    csv << std::setprecision(17)
        << "time_s,bus_pos_V,bus_neg_V,far_bus_pos_V,far_bus_neg_V,va_V,vb_V,vc_V,ia_load_A,ib_load_A,ic_load_A,source_pos_V,source_neg_V,far_input_pos_V,far_input_neg_V,total_load_power_W,carrier,modulation,dcdc_duty,invA_gate\n";
    auto save = [&](std::int64_t n) {
        double power = 0;
        for (int j = 36; j < 54; ++j) power += sample.nodes[j] * sample.nodes[j] / 7;
        csv << n * dt << ',' << sample.nodes[2] << ',' << sample.nodes[18]
            << ',' << sample.nodes[10] << ',' << sample.nodes[26]
            << ',' << sample.nodes[36] << ',' << sample.nodes[37] << ',' << sample.nodes[38]
            << ',' << sample.nodes[36] / 7 << ',' << sample.nodes[37] / 7 << ',' << sample.nodes[38] / 7
            << ',' << sample.nodes[0] << ',' << sample.nodes[1]
            << ',' << sample.nodes[34] << ',' << sample.nodes[35] << ',' << power
            << ',' << carrier << ',' << modulation << ',' << duty << ',' << inverterGates[0][0] << '\n';
    };
    save(0);
    std::string status = "completed";
    std::int64_t completed = 0;
    double maximumCheckedVoltage = 0;
    int maximumNode = 0;
    const auto started = std::chrono::steady_clock::now();
    for (std::int64_t n = 1; n <= steps; ++n) {
        const std::int64_t stepStart = n - 1;
        if (stepStart % controlEvery == 0) {
            const std::int64_t tick = stepStart / controlEvery;
            carrier = (tick % carrierTicks) / static_cast<double>(carrierTicks);
            const double ramp = std::min(1.0, std::max(0.0, (tick - activationTick) * controlDt / .002));
            const double targetDuty = scenario == "busstep" && tick >= eventTick ? .6 : .8;
            duty = .5 + (targetDuty - .5) * ramp;
            for (int k = 0; k < 2; ++k) {
                enabled[k] = tick >= activationTick;
                dcdcGates[k][0] = carrier < duty;
                dcdcGates[k][1] = !dcdcGates[k][0];
            }
            const double invRamp = std::min(1.0, std::max(0.0, (tick - inverterTick) * controlDt / .002));
            modulation = (scenario == "acstep" && tick >= eventTick ? .5 : 1) * invRamp;
            for (int phase = 0; phase < 3; ++phase) {
                const double reference = modulation * std::sin(2 * pi * fundamentalHz * tick * controlDt - 2 * pi * phase / 3);
                for (int k = 0; k < 6; ++k) {
                    inverterGates[k][phase] = carrier < .5 * (1 + reference);
                    enabled[k + 2] = tick >= inverterTick;
                }
            }
        }
        advance(sample, dcdcGates, inverterGates, enabled);
        completed = n;
        bool nonfinite = false;
        // Monitor representative bus/phase values each step; scan all 108 outputs every 100 steps.
        for (int j : {2, 18, 36}) nonfinite = nonfinite || !std::isfinite(sample.nodes[j]);
        if (n % 100 == 0 || n < 2000 || nonfinite || n == steps) {
            for (int j = 0; j < 54; ++j) {
                const double value = std::abs(sample.nodes[j]);
                nonfinite = nonfinite || !std::isfinite(value) || !std::isfinite(sample.outputs[j]);
                if (std::isfinite(value) && value > maximumCheckedVoltage) {
                    maximumCheckedVoltage = value;
                    maximumNode = j + 1;
                }
            }
        }
        if (nonfinite) status = "nonfinite";
        else if (maximumCheckedVoltage > 1e8) status = "voltage_guard";
        const double t = n * dt;
        if (n % globalEvery == 0 || (t >= focusStart && t <= focusEnd && n % focusEvery == 0)
            || std::abs(t - eventTime) < 50e-6 || n < 1000 || status != "completed" || n == steps)
            save(n);
        if (status != "completed") break;
    }
    const double wall = std::chrono::duration<double>(std::chrono::steady_clock::now() - started).count();
    std::ofstream json(prefix + ".json");
    json << std::setprecision(17)
         << "{\n\"scenario\":\"" << scenario << "\",\n\"method\":\"unmodified_codegen_two_leg_euler\",\n"
         << "\"status\":\"" << status << "\",\n\"dt_s\":" << dt
         << ",\n\"requested_duration_s\":" << duration << ",\n\"event_time_s\":" << eventTime
         << ",\n\"completed_steps\":" << completed << ",\n\"last_time_s\":" << completed * dt
         << ",\n\"wall_seconds\":" << wall << ",\n\"maximum_checked_finite_voltage_V\":" << maximumCheckedVoltage
         << ",\n\"maximum_node\":" << maximumNode << ",\n\"node_count\":54,\n\"component_output_count\":54"
         << ",\n\"full_scan_stride_steps\":100,\n\"carrier_Hz\":" << carrierHz
         << ",\n\"carrier_ticks\":" << carrierTicks << ",\n\"control_dt_s\":" << controlDt
         << ",\n\"fundamental_Hz_assumed\":" << fundamentalHz << "\n}\n";
    std::cout << prefix << ": " << status << ", t=" << completed * dt << " s, steps=" << completed
              << ", wall=" << wall << " s\n";
    return status == "completed" ? 0 : 2;
}
